import json, re
from pathlib import Path
manifest = json.loads(Path('/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54mini_all/first_10_queries/q01/logs/q01.manifest.json').read_text())
docket_re = re.compile(r'\\b\\d{2}-\\d+(?:-\\d+)?\\b')
start_re = re.compile(r'"'^'"\\s*No(?:s)?\\.?(?:\\s*|"'$)'"')
numline_re = re.compile(r'"'^'"\\s*\\d{2}-\\d+(?:-\\d+)?(?:[\\s,]+\\d{2}-\\d+(?:-\\d+)?)*\\s*"'$'"')
marker_re = re.compile(r'(?:D\\.C\\.|BAP No\\.|Agency Nos?\\.|OPINION|ORDER|SUMMARY|MEMORANDUM|Appeal from|Before:|Filed|Submitted)')

def extract(text):
    lines = text.splitlines()
    nums, seen = [], set()
    for i, line in enumerate(lines):
        if not start_re.match(line):
            continue
        window = lines[i:i+20]
        if not any(marker_re.search(w) for w in window[1:]):
            continue
        for j, w in enumerate(window):
            if j == 0 or numline_re.match(w):
                for tok in docket_re.findall(w):
                    if tok not in seen:
                        seen.add(tok)
                        nums.append(tok)
    return ', '.join(nums) if nums else 'NOT_FOUND'

miss = []
for d in manifest['documents']:
    ans = extract(Path(d['doc_path']).read_text())
    if ans == 'NOT_FOUND':
        miss.append(d['doc_name'])
print('miss', len(miss))
for name in miss[:20]:
    print(name)
